export function evaluate({ inputs, time }) {
  const u = inputs.launchSpeed;
  const g = inputs.gravity;
  const m = inputs.mass;
  const t = Math.max(0, time);
  const v = u - g * t;
  const y = u * t - 0.5 * g * t * t;
  const apexTime = u / g;
  const apexHeight = (u * u) / (2 * g);
  const force = m * g;
  let motionState = "Ready to toss";
  if (t > 0 && t < apexTime) motionState = "Rising";
  else if (Math.abs(t - apexTime) < 0.05) motionState = "At the top";
  else if (t > apexTime && y >= 0) motionState = "Falling";
  else if (y < 0) motionState = "Back at launch height";
  const objects = [];
  objects.push(...sdk.panel({ x: 20, y: 35, w: 290, h: 360, title: "The motion", state: motionState }));
  objects.push(sdk.axis("axis.height", { x: 50, y: 350, length: 240, orientation: "y", min: 0, max: 2.2, ticks: [0, 0.5, 1.0, 1.5, 2.0], label: "Height", unit: "m" }));
  const ballY = 350 - (y / 2.2) * 240;
  objects.push(sdk.circle("ball.toss", 160, ballY, 26, { role: "output" }));
  objects.push(...sdk.vector("vec.v", { x: 160, y: ballY }, { value: v, direction: "up" }, { scale: 15, label: "v", role: "observed" }));
  objects.push(...sdk.vector("vec.a", { x: 190, y: ballY }, { value: -g, direction: "up" }, { scale: 15, label: "a", role: "prediction" }));
  objects.push(...sdk.callout(210, ballY - 20, [
    `v: ${sdk.format(v, 2)} m/s`,
    `a: ${sdk.format(-g, 2)} m/s^2`,
    `Fg: ${sdk.format(force, 2)} N`
  ], { role: "output" }));
  const plotPoints = [];
  const dt = apexTime * 2 / 20;
  for (let i = 0; i <= 20; i++) {
    const st = i * dt;
    plotPoints.push({ x: st, y: u - g * st });
  }
  objects.push(sdk.plot("plot.vt", {
    x: 330,
    y: 35,
    w: 290,
    h: 360,
    axes: {
      x: { label: "Time", min: 0, max: Math.max(1.8, apexTime * 2), unit: "s" },
      y: { label: "Velocity", min: -5.5, max: 5.5, unit: "m/s" }
    },
    series: [
      { label: "v(t)", kind: "line", points: plotPoints }
    ],
    marker: { x: t, y: v, label: "t" }
  }));
  objects.push(sdk.text("plot.vt.note", 340, 385, "Slope a = -g", { role: "neutral" }));
  return {
    frame: {
      width: 640,
      height: 420,
      objects,
      readouts: [
        { id: "velocity", value: v },
        { id: "acceleration", value: -g },
        { id: "force", value: force },
        { id: "motionState", value: motionState }
      ]
    },
    quantities: {
      launchSpeed: u,
      gravity: g,
      mass: m,
      apexTime,
      apexHeight,
      height: y,
      velocity: v,
      acceleration: -g,
      force
    }
  };
}
